\",\n      \"Solanum\",\n      \"Solanum tuberosum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/2930262\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"abelmoschus-esculentus\",\n    \"common\": \"Okra\",\n    \"name\": \"Abelmoschus esculentus\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Malvales\",\n      \"Malvaceae\",\n      \"Abelmoschus\",\n      \"Abelmoschus esculentus\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/3152707\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"hibiscus-rosa-sinensis\",\n    \"common\": \"Hibiscus\",\n    \"name\": \"Hibiscus rosa-sinensis\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Malvales\",\n      \"Malvaceae\",\n      \"Hibiscus\",\n      \"Hibiscus rosa-sinensis\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/3152559\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"mangifera-indica\",\n    \"common\": \"Mango\",\n    \"name\": \"Mangifera indica\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Sapindales\",\n      \"Anacardiaceae\",\n      \"Mangifera\",\n      \"Mangifera indica\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/3190638\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"carica-papaya\",\n    \"common\": \"Papaya\",\n    \"name\": \"Carica papaya\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Brassicales\",\n      \"Caricaceae\",\n      \"Carica\",\n      \"Carica papaya\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/2874484\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"theobroma-cacao\",\n    \"common\": \"Cacao\",\n    \"name\": \"Theobroma cacao\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Malvales\",\n      \"Malvaceae\",\n      \"Theobroma\",\n      \"Theobroma cacao\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/3152205\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"helianthus-annuus\",\n    \"common\": \"Sunflower\",\n    \"name\": \"Helianthus annuus\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Magnoliopsida\",\n      \"Asterales\",\n      \"Asteraceae\",\n      \"Helianthus\",\n      \"Helianthus annuus\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named plant species example. Plant phylum is often called division in school texts; monocot/dicot groupings and source class ranks may differ.\",\n    \"source\": \"https://www.gbif.org/species/9206251\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"pinus-sylvestris\",\n    \"common\": \"Scots pine\",\n    \"name\": \"Pinus sylvestris\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Pinopsida\",\n      \"Pinales\",\n      \"Pinaceae\",\n      \"Pinus\",\n      \"Pinus sylvestris\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A gymnosperm example with seeds borne in cones; it is not a flowering plant.\",\n    \"source\": \"https://www.gbif.org/species/5285637\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"polytrichum-commune\",\n    \"common\": \"Common haircap moss\",\n    \"name\": \"Polytrichum commune\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Bryophyta\",\n      \"Polytrichopsida\",\n      \"Polytrichales\",\n      \"Polytrichaceae\",\n      \"Polytrichum\",\n      \"Polytrichum commune\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A moss example. Bryophytes differ from vascular plants; do not place all green land plants in flowering-plant groups.\",\n    \"source\": \"https://www.gbif.org/species/2683084\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"dryopteris-filix-mas\",\n    \"common\": \"Male fern\",\n    \"name\": \"Dryopteris filix-mas\",\n    \"group\": \"Plants\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Tracheophyta\",\n      \"Polypodiopsida\",\n      \"Polypodiales\",\n      \"Dryopteridaceae\",\n      \"Dryopteris\",\n      \"Dryopteris filix-mas\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A fern example: a vascular plant that reproduces by spores, rather than flowers and seeds.\",\n    \"source\": \"https://www.gbif.org/species/5275132\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"saccharomyces-cerevisiae\",\n    \"common\": \"Baker’s yeast\",\n    \"name\": \"Saccharomyces cerevisiae\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Ascomycota\",\n      \"Saccharomycetes\",\n      \"Saccharomycetales\",\n      \"Saccharomycetaceae\",\n      \"Saccharomyces\",\n      \"Saccharomyces cerevisiae\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A unicellular fungus used in baking and fermentation. Unicellular does not mean bacterial.\",\n    \"source\": \"https://www.gbif.org/species/7440012\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"agaricus-bisporus\",\n    \"common\": \"Button mushroom\",\n    \"name\": \"Agaricus bisporus\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Basidiomycota\",\n      \"Agaricomycetes\",\n      \"Agaricales\",\n      \"Agaricaceae\",\n      \"Agaricus\",\n      \"Agaricus bisporus\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named fungus example. Fungal phylum and class names differ between older school schemes and newer reference hierarchies.\",\n    \"source\": \"https://www.gbif.org/species/5243447\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"rhizopus-stolonifer\",\n    \"common\": \"Black bread mould\",\n    \"name\": \"Rhizopus stolonifer\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Mucoromycota\",\n      \"Mucoromycetes\",\n      \"Mucorales\",\n      \"Rhizopodaceae\",\n      \"Rhizopus\",\n      \"Rhizopus stolonifer\"\n    ],\n    \"aliases\": [\n      \"Rhizopus nigricans\"\n    ],\n    \"note\": \"An example of bread mould. Older texts use Zygomycota/Zygomycetes; this reference uses a different ranked fungal classification.\",\n    \"source\": \"https://www.gbif.org/species/2558944\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"aspergillus-niger\",\n    \"common\": \"Black Aspergillus mould\",\n    \"name\": \"Aspergillus niger\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Ascomycota\",\n      \"Eurotiomycetes\",\n      \"Eurotiales\",\n      \"Aspergillaceae\",\n      \"Aspergillus\",\n      \"Aspergillus niger\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named fungus example. Fungal phylum and class names differ between older school schemes and newer reference hierarchies.\",\n    \"source\": \"https://www.gbif.org/species/3465658\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"penicillium-chrysogenum\",\n    \"common\": \"Penicillium mould\",\n    \"name\": \"Penicillium chrysogenum\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Ascomycota\",\n      \"Eurotiomycetes\",\n      \"Eurotiales\",\n      \"Aspergillaceae\",\n      \"Penicillium\",\n      \"Penicillium chrysogenum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named mould example; some famous penicillin-producing strains formerly called P. chrysogenum are now identified as P. rubens.\",\n    \"source\": \"https://www.gbif.org/species/3466349\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"ustilago-maydis\",\n    \"common\": \"Corn smut\",\n    \"name\": \"Ustilago maydis\",\n    \"group\": \"Fungi\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Fungi\",\n      \"Basidiomycota\",\n      \"Ustilaginomycetes\",\n      \"Ustilaginales\",\n      \"Ustilaginaceae\",\n      \"Ustilago\",\n      \"Ustilago maydis\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A named fungus example. Fungal phylum and class names differ between older school schemes and newer reference hierarchies.\",\n    \"source\": \"https://www.gbif.org/species/8092646\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"amoeba-proteus\",\n    \"common\": \"Amoeba\",\n    \"name\": \"Amoeba proteus\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Protozoa\",\n      \"Amoebozoa\",\n      \"Lobosa\",\n      \"Amoebida\",\n      \"Amoebidae\",\n      \"Amoeba\",\n      \"Amoeba proteus\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Often taught in Protista with older group names such as Rhizopoda. Here the source uses kingdom Protozoa, phylum Amoebozoa and class Lobosa.\",\n    \"source\": \"https://www.gbif.org/species/5425264\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"paramecium-caudatum\",\n    \"common\": \"Paramecium\",\n    \"name\": \"Paramecium caudatum\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Chromista\",\n      \"Ciliophora\",\n      \"Oligohymenophorea\",\n      \"Peniculida\",\n      \"Parameciidae\",\n      \"Paramecium\",\n      \"Paramecium caudatum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A ciliate often placed in school kingdom Protista. This reference places it in Chromista. The teaching group filter is not a kingdom label.\",\n    \"source\": \"https://www.gbif.org/species/8122199\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"euglena-gracilis\",\n    \"common\": \"Euglena\",\n    \"name\": \"Euglena gracilis\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Protozoa\",\n      \"Euglenozoa\",\n      \"Euglenoidea\",\n      \"Euglenida\",\n      \"Euglenaceae\",\n      \"Euglena\",\n      \"Euglena gracilis\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Frequently taught as Protista, with older phylum names such as Euglenophyta. The GBIF profile uses Protozoa and Euglenozoa; systems vary.\",\n    \"source\": \"https://www.gbif.org/species/7465722\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"plasmodium-falciparum\",\n    \"common\": \"Malaria parasite\",\n    \"name\": \"Plasmodium falciparum\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Chromista\",\n      \"Myzozoa\",\n      \"Aconoidasida\",\n      \"Haemospororida\",\n      \"Plasmodiidae\",\n      \"Plasmodium\",\n      \"Plasmodium falciparum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"One malaria parasite species; malaria is not caused by every protist. Often taught in Protista; source kingdom names may differ.\",\n    \"source\": \"https://www.gbif.org/species/10540993\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"trypanosoma-brucei\",\n    \"common\": \"Sleeping-sickness trypanosome\",\n    \"name\": \"Trypanosoma brucei\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Protozoa\",\n      \"Euglenozoa\",\n      \"Kinetoplastea\",\n      \"Trypanosomatida\",\n      \"Trypanosomatidae\",\n      \"Trypanosoma\",\n      \"Trypanosoma brucei\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Includes lineages associated with African trypanosomiasis; not every member of the genus has the same host or disease role.\",\n    \"source\": \"https://www.gbif.org/species/7822322\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"chlamydomonas-reinhardtii\",\n    \"common\": \"Chlamydomonas green alga\",\n    \"name\": \"Chlamydomonas reinhardtii\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Chlorophyta\",\n      \"Chlorophyceae\",\n      \"Volvocales\",\n      \"Chlamydomonadaceae\",\n      \"Chlamydomonas\",\n      \"Chlamydomonas reinhardtii\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A unicellular green alga; often grouped with protists in school courses. GBIF places it within Plantae. Protists and algae is a study filter, not a formal kingdom.\",\n    \"source\": \"https://www.gbif.org/species/5271221\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"volvox-carteri\",\n    \"common\": \"Volvox green alga\",\n    \"name\": \"Volvox carteri\",\n    \"group\": \"Protists and algae\",\n    \"ranks\": [\n      \"Eukarya\",\n      \"Plantae\",\n      \"Chlorophyta\",\n      \"Chlorophyceae\",\n      \"Volvocales\",\n      \"Volvocaceae\",\n      \"Volvox\",\n      \"Volvox carteri\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A colonial green alga. School resources may group it with protists; this source places it in Plantae.\",\n    \"source\": \"https://www.gbif.org/species/2639377\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"escherichia-coli\",\n    \"common\": \"Gut bacterium E. coli\",\n    \"name\": \"Escherichia coli\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Bacteria\",\n      \"Bacteria\",\n      \"Proteobacteria\",\n      \"Gammaproteobacteria\",\n      \"Enterobacterales\",\n      \"Enterobacteriaceae\",\n      \"Escherichia\",\n      \"Escherichia coli\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Strains differ greatly; many occur in animal intestines, while some cause illness. Proteobacteria is an older widely used name for Pseudomonadota.\",\n    \"source\": \"https://www.gbif.org/species/11286021\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"bacillus-subtilis\",\n    \"common\": \"Hay bacillus\",\n    \"name\": \"Bacillus subtilis\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Bacteria\",\n      \"Bacteria\",\n      \"Firmicutes\",\n      \"Bacilli\",\n      \"Bacillales\",\n      \"Bacillaceae\",\n      \"Bacillus\",\n      \"Bacillus subtilis\"\n    ],\n    \"aliases\": [],\n    \"note\": \"A commonly studied spore-forming bacterium. Firmicutes is an older widely used name for Bacillota.\",\n    \"source\": \"https://www.gbif.org/species/10826006\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"vibrio-cholerae\",\n    \"common\": \"Cholera bacterium\",\n    \"name\": \"Vibrio cholerae\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Bacteria\",\n      \"Bacteria\",\n      \"Proteobacteria\",\n      \"Gammaproteobacteria\",\n      \"Enterobacterales\",\n      \"Vibrionaceae\",\n      \"Vibrio\",\n      \"Vibrio cholerae\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Traditional school Monera combines prokaryotes. Modern domain systems separate Bacteria and Archaea; bacterial phylum names can vary between references.\",\n    \"source\": \"https://www.gbif.org/species/3222442\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"staphylococcus-aureus\",\n    \"common\": \"Staphylococcus\",\n    \"name\": \"Staphylococcus aureus\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Bacteria\",\n      \"Bacteria\",\n      \"Firmicutes\",\n      \"Bacilli\",\n      \"Staphylococcales\",\n      \"Staphylococcaceae\",\n      \"Staphylococcus\",\n      \"Staphylococcus aureus\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Traditional school Monera combines prokaryotes. Modern domain systems separate Bacteria and Archaea; bacterial phylum names can vary between references.\",\n    \"source\": \"https://www.gbif.org/species/3227657\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"rhizobium-leguminosarum\",\n    \"common\": \"Nitrogen-fixing Rhizobium\",\n    \"name\": \"Rhizobium leguminosarum\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Bacteria\",\n      \"Bacteria\",\n      \"Proteobacteria\",\n      \"Alphaproteobacteria\",\n      \"Rhizobiales\",\n      \"Rhizobiaceae\",\n      \"Rhizobium\",\n      \"Rhizobium leguminosarum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Traditional school Monera combines prokaryotes. Modern domain systems separate Bacteria and Archaea; bacterial phylum names can vary between references.\",\n    \"source\": \"https://www.gbif.org/species/11046672\",\n    \"checked\": \"2026-11-03\"\n  },\n  {\n    \"id\": \"halobacterium-salinarum\",\n    \"common\": \"Salt-loving archaeon\",\n    \"name\": \"Halobacterium salinarum\",\n    \"group\": \"Bacteria and archaea\",\n    \"ranks\": [\n      \"Archaea\",\n      \"Archaea\",\n      \"Halobacteriota\",\n      \"Halobacteria\",\n      \"Halobacteriales\",\n      \"Halobacteriaceae\",\n      \"Halobacterium\",\n      \"Halobacterium salinarum\"\n    ],\n    \"aliases\": [],\n    \"note\": \"Despite the genus name, this is an archaeon, not a bacterium. Traditional Monera combines lineages separated by modern domains.\",\n    \"source\": \"https://www.gbif.org/species/7357253\",\n    \"checked\": \"2026-11-03\"\n  }\n]\n", "src/lib/biology/lessons.ts": "export type LessonId='cells'|'mitosis'|'meiosis'|'transpiration'|'classification'|'life-processes';\nexport type Step={name:string;detail:string};\nexport type Question={prompt:string;choices:string[];answer:number;why:string};\nexport type Lesson={title:string;intro:string;principle:string;steps:Step[];questions:Question[];investigation:string[];teacher:string;misconception:string;source:string;limit:string};\nconst q=(prompt:string,choices:string[],answer:number,why:string):Question=>({prompt,choices,answer,why});\nexport const lessons:Record<LessonId,Lesson>={\n cells:{title:'Cells and organelles',intro:'Compare simplified plant and animal cells. Select an organelle to connect its structure with its function.',principle:'Cells are the basic units of living organisms; structures support different functions.',steps:[\n {name:'Cell membrane',detail:'A selectively permeable boundary controls exchange with the surroundings. Plant cells have a membrane inside the cell wall.'},\n {name:'Cytoplasm',detail:'The cytosol is fluid inside the cell; many metabolic reactions occur here. Cytoplasm includes the cytosol and organelles outside the nucleus.'},\n {name:'Nucleus',detail:'Contains most of the cell’s DNA. Gene expression helps regulate cell activities. Not every specialised animal cell retains a nucleus.'},\n {name:'Mitochondrion',detail:'Supports aerobic respiration and ATP production. Plant cells have mitochondria as well as chloroplasts.'},\n {name:'Ribosomes',detail:'Build proteins using instructions carried by messenger RNA. They occur free in the cytoplasm and on rough endoplasmic reticulum.'},\n {name:'Cell wall',detail:'The cellulose-rich plant cell wall supports and protects the cell. Animal cells do not have a cell wall.'},\n {name:'Chloroplast',detail:'In photosynthetic plant tissues, chloroplasts capture light energy for photosynthesis. Many root cells lack chloroplasts.'},\n {name:'Central vacuole',detail:'A large compartment in many mature plant cells stores water and solutes. Turgor pressure contributes to support.'}],\n questions:[q('Which structure makes proteins?',['Nucleus','Ribosomes','Cell wall'],1,'Ribosomes assemble proteins; the nucleus contains genetic instructions.'),q('Which comparison is correct?',['Plants have no mitochondria','All plant cells have chloroplasts','Plant and animal cells have membranes'],2,'Both have membranes. Photosynthetic plant cells also contain chloroplasts.'),q('Which helps support a typical mature plant cell?',['Cell wall and turgor','Only a nucleus','Only ribosomes'],0,'The wall resists the pressure generated by water inside the cell.')],\n investigation:['Compare both cell types and record four shared structures.','Select the membrane and explain why a wall cannot replace it.','Explain why a root cell may lack chloroplasts but still require mitochondria.'],teacher:'Ask pairs to act as an organelle and a cell: one names a task, the other selects the structure. Compare leaf and root cells before generalising about plants.',misconception:'Plant cells respire too. Not every plant cell contains chloroplasts. The illustration omits ER, Golgi and other structures.',source:'4-3-eukaryotic-cells',limit:'Selected organelles only; not a scale drawing or a complete inventory.'},\n mitosis:{title:'Mitosis and the cell cycle',intro:'Step through DNA replication, chromosome alignment, separation and the production of two daughter cells.',principle:'One DNA replication precedes one nuclear division; chromosome set number is maintained.',steps:[\n {name:'G1 · before replication',detail:'Our simplified diploid cell has 2n = 4: two homologous pairs. Each chromosome contains one DNA molecule.'},\n {name:'S/G2 · DNA copied',detail:'DNA replicates during S phase. There are still 4 chromosomes, now with 8 sister chromatids; counting is by centromeres, not DNA strands.'},\n {name:'Prophase / prometaphase',detail:'Chromosomes condense, the spindle forms and the nuclear envelope breaks down. Each sister chromatid attaches toward an opposite pole.'},\n {name:'Metaphase',detail:'Replicated chromosomes align individually at the equator. Homologous chromosomes do not pair as tetrads.'},\n {name:'Anaphase',detail:'Sister chromatids separate and become daughter chromosomes. Each pole receives the same chromosome complement.'},\n {name:'Telophase and cytokinesis',detail:'Nuclei reform and cytoplasm divides. Two daughter cells each have 2n = 4 in this model, usually genetically alike except for new mutations.'}],\n questions:[q('What separates during mitotic anaphase?',['Homologous pairs only','Sister chromatids','Whole nuclei'],1,'Sister chromatids separate and each becomes a chromosome.'),q('After S phase, our 2n = 4 cell contains…',['4 chromosomes, 8 chromatids','8 chromosomes, 8 chromatids','2 chromosomes'],0,'Replication doubles DNA content, not the number of centromeres.'),q('What is the usual result here?',['Four haploid cells','Two diploid cells','One gamete'],1,'One division maintains the starting ploidy.')],investigation:['Pause at S/G2 and count chromosomes separately from chromatids.','Compare metaphase with anaphase. Track one colour to both poles.','Draw the two daughter cells and justify their chromosome number.'],teacher:'Assign pupils the roles of chromosomes and spindle fibres using cards. Ask the class to predict the next stage before advancing. Keep chromosome counts separate from DNA quantity.',misconception:'DNA copying is in interphase, not prophase. Mitosis can also occur in haploid cells; this example starts diploid.',source:'10-2-the-cell-cycle',limit:'A schematic 2n = 4 animal-cell example; stages have equal playback durations, not real biological durations.'},\n meiosis:{title:'Meiosis and genetic variation',intro:'Follow one DNA replication and two divisions. Compare homologous chromosome separation with sister chromatid separation.',principle:'Meiosis I reduces chromosome sets; meiosis II separates sister chromatids without another S phase.',steps:[\n {name:'Before S phase · 2n = 4',detail:'Two homologous pairs are shown: one long and one short. Blue and coral indicate the two parental origins, not sex chromosomes.'},\n {name:'DNA replication',detail:'Each of 4 chromosomes is copied into two sister chromatids. DNA replicates once before meiosis I.'},\n {name:'Prophase I · crossing over',detail:'Homologues pair. Non-sister chromatids exchange corresponding DNA segments; the marked tips show one illustrative crossover.'},\n {name:'Metaphase I',detail:'Homologous pairs align together. Their orientation is independent; use the orientation control to compare two possible arrangements.'},\n {name:'Anaphase I',detail:'Homologues separate, while sister chromatids remain joined. Each pole receives one member of each homologous pair.'},\n {name:'After meiosis I',detail:'Two haploid cells each contain n = 2 replicated chromosomes. Haploid does not mean that every chromosome has a single chromatid.'},\n {name:'Metaphase II',detail:'With no intervening DNA replication, replicated chromosomes align individually in each haploid cell.'},\n {name:'Anaphase II',detail:'Sister chromatids separate in both cells. The exchanged DNA segments can make sisters genetically different.'},\n {name:'Four haploid products',detail:'Each product has n = 2 single-chromatid chromosomes. Animal gametogenesis may produce unequal cytoplasm, as in oogenesis; four equal circles are a schematic.'}],\n questions:[q('What separates in meiosis I?',['Sister chromatids','Homologous chromosomes','Ribosomes'],1,'The reduction division separates homologues; sisters remain attached.'),q('Is there an S phase between meiosis I and II?',['Yes','No'],1,'One replication precedes the two divisions.'),q('Where does crossing over occur?',['Non-sister chromatids of homologues','Between unrelated cells','Only after fertilisation'],0,'Corresponding segments exchange between paired homologous chromosomes.')],investigation:['Compare 2n = 4 before S phase with n = 2 after division I.','Change orientation at metaphase I and track the short pair.','Toggle crossing over and compare the marked segments in all four products.'],teacher:'Give each pair two colours of long and short chromosome cards. Have students predict division-I products, then contrast the two types of separation with mitosis.',misconception:'Haploid chromosomes can still be replicated. Independent assortment and crossing over are distinct. Plant meiosis produces spores; gametes are not the universal direct product.',source:'11-1-the-process-of-meiosis',limit:'Two homologous pairs, one illustrative crossover and two selected orientations; not all genetic outcomes or actual cell geometry.'},\n transpiration:{title:'Transpiration in plants',intro:'Adjust humidity, air movement, temperature and stomatal opening. Compare a simplified relative water-loss index.',principle:'Evaporation and diffusion at leaves contribute to tension that draws water up xylem.',steps:[{name:'Root uptake',detail:'Water enters roots along a water-potential gradient. Roots do not act as a mechanical pump for the whole transpiration stream.'},{name:'Xylem transport',detail:'Cohesion and adhesion help maintain a continuous water column under tension. This model assumes an adequate water supply.'},{name:'Leaf evaporation',detail:'Water evaporates from moist mesophyll surfaces into leaf air spaces.'},{name:'Stomatal diffusion',detail:'Water vapour diffuses through stomata toward drier air. Guard cells regulate the aperture.'}],questions:[q('With everything else fixed, higher humidity usually…',['Lowers transpiration','Raises it indefinitely','Stops photosynthesis instantly'],0,'A smaller vapour gradient reduces diffusion.'),q('Which tissue carries this water stream?',['Phloem','Xylem','Epidermis only'],1,'Xylem transports water and dissolved mineral ions.'),q('Does this index predict field water loss in mL/hour?',['Yes','No'],1,'It is an illustrative relative index; leaf area and plant physiology are omitted.')],investigation:['Record the index at 20%, 50% and 80% humidity, keeping other controls fixed.','Repeat for air movement. Explain why it has diminishing influence here.','Close stomata and describe the trade-off between conserving water and taking in carbon dioxide.'],teacher:'Ask groups to predict an environmental effect before changing one variable. Keep a results table and compare fair tests. Discuss why drought-induced stomatal closure can reverse a simple temperature trend.',misconception:'Transpiration is water-vapour loss, not the upward water stream itself. A potometer estimates water uptake, which is not identical to water lost.',source:'30-5-transport-of-water-and-solutes-in-plants',limit:'Illustrative relative index, no physical rate units. Fixed water supply, no wilting, leaf-area variation, cuticular loss or automatic stomatal feedback.'},\n classification:{title:'Classification and scientific names',intro:'Search 90 organisms, compare their Domain and KPCOFGS ranks, and practise scientific names. Includes common animals, crops, fungi, protists, bacteria and an archaeon.',principle:'Nested taxa organise organisms; a scientific species name combines genus with specific epithet.',steps:[\n {name:'Domain',detail:'A level above kingdom. Compare Bacteria, Archaea and Eukarya. Domain here is mapped from the source kingdom, using the three-domain teaching framework.'},\n {name:'Kingdom',detail:'The source may use Animalia, Plantae, Fungi, Protozoa, Chromista, Bacteria or Archaea. These labels do not form the traditional five-kingdom scheme. Check the notes before comparing textbook answers.'},\n {name:'Phylum / Division',detail:'A broad grouping within a kingdom. Plant texts often use division in place of phylum. Compare organisms within the same source system.'},\n {name:'Class',detail:'A grouping within a phylum. Mammalia and Insecta are familiar examples. Reference systems may rank some groups differently, and not every record assigns this rank.'},\n {name:'Order',detail:'A grouping within a class when both ranks are assigned. Look for similarities and differences between two organisms, rather than judging from appearance alone.'},\n {name:'Family',detail:'A grouping above genus. For example, grasses include Poaceae and legumes include Fabaceae. Select maize/rice or cowpea/groundnut to compare.'},\n {name:'Genus',detail:'A genus groups related species. Capitalise and italicise the genus in a scientific name. Human and cat belong to different genera, Homo and Felis.'},\n {name:'Species',detail:'Use the full binomial: genus plus a lower-case specific epithet, both italicised. Common names can cover many species. Synonyms and subspecies need attention when matching a specimen to a reference.'}],questions:[q('Which rank is immediately above genus?',['Species','Family','Class'],1,'The sequence is order, family, genus, species.'),q('Which is correctly written?',['homo Sapiens','Homo sapiens','Sapiens'],1,'The genus starts with a capital and the epithet is lower case; italicise both.'),q('A missing rank in a reference should be…',['Invented from appearance','Marked as unassigned','Filled with the genus name'],1,'A reference can omit a rank. State the source instead of inventing a taxon.'),q('Monera and Protista are…',['Universal modern domains','Traditional teaching groupings','Two animal families'],1,'Modern sources split these older groupings differently. Always name the classification system.')],investigation:['Search and compare one Nigerian crop with another. Find their narrowest displayed shared rank.','Compare a vertebrate with an invertebrate, then a plant with a fungus. Explain which ranks differ.','Choose maize and rice, then cat and lion. Predict a selected rank before revealing it.','Compare Amoeba, Euglena and a bacterium. Explain why study groups are not necessarily kingdoms.','Find an unassigned rank or a synonym. Read the source note and explain how this changes marking a textbook answer.'],teacher:'Teams choose two organisms, hide the selected rank and invite predictions. Rotate the operator and explainer. Discuss any source differences rather than treating one ranked scheme as universal.',misconception:'A classification is not a ladder of progress. Broad common names are not species names. Identical rank labels across different systems need not describe identical evolutionary groups.',source:'20-1-organizing-life-on-earth',limit:'A saved GBIF Backbone reference collection with three-domain labels added. Ranks and accepted names can differ between sources; unassigned ranks are explicit. Study filters are not taxonomic ranks.'},\n 'life-processes':{title:'Characteristics of living things',intro:'Explore life processes and evaluate evidence. Mnemonics vary; use the named processes and the combined evidence rather than one sign alone.',principle:'Life is identified using interacting properties across cells, organisms and populations, not motion alone.',steps:[{name:'Movement',detail:'Animals may move from place to place; plants also show growth movements and internal transport. Motion alone does not establish life.'},{name:'Respiration',detail:'Cells release usable energy from chemical substrates. Cellular respiration is distinct from breathing and can be aerobic or anaerobic.'},{name:'Nutrition',detail:'Organisms obtain materials and energy. Photosynthesis is a mode of autotrophic nutrition; animals obtain organic nutrients by feeding.'},{name:'Sensitivity / irritability',detail:'Organisms detect and respond to stimuli, such as light, touch or chemical signals.'},{name:'Growth and development',detail:'Living systems grow through cellular processes and develop organised structures; simple external accumulation is not sufficient evidence of life.'},{name:'Excretion',detail:'Removal of metabolic wastes such as carbon dioxide or nitrogenous compounds. Egestion of undigested food is different.'},{name:'Reproduction',detail:'New organisms arise from living systems. A sterile individual can still be alive; reproduction describes continuation of lineages.'},{name:'Death',detail:'Individual life ends through irreversible loss of integrated function. Death alone is not a diagnostic test for life.'},{name:'Competition',detail:'Organisms may compete for limited resources. Competition also occurs in other systems, so it is not sufficient evidence on its own.'},{name:'Adaptation',detail:'Heritable traits can become more common across generations through natural selection. This differs from short-term acclimatisation of an individual.'}],questions:[q('A car moves and uses fuel. Is that alone evidence it is alive?',['Yes','No'],1,'Life requires a coordinated set of properties including cellular organisation.'),q('Excretion is…',['Removal of metabolic waste','Removal of undigested food','Only movement'],0,'Egestion concerns undigested food; excretion concerns metabolic wastes.'),q('A sterile animal is…',['Not alive','Still alive'],1,'An individual need not reproduce to be alive.')],investigation:['For each process, propose a plant example and an animal example.','Compare a seed, a flame and a moving vehicle using several lines of evidence.','Explain respiration versus breathing and adaptation versus acclimatisation.'],teacher:'Ask groups to sort evidence cards into strong, weak and insufficient evidence for life. Include a dormant seed so lack of visible movement is not treated as proof of non-life.',misconception:'MRNIGERDCA is a memory aid, not a universal definition. Homeostasis, cellular organisation and evolution also matter; the processes should be considered together.',source:'1-2-themes-and-concepts-of-biology',limit:'A conceptual explorer, not a biological test or a claim that every process must be visibly present in every individual.'}\n};\nexport function transpirationIndex(humidity:number,wind:number,temperature:number,opening:number){\n const clamp=(x:number,lo:number,hi:number)=>Math.min(hi,Math.max(lo,x));\n return 100*(1-clamp(humidity,0,100)/100)*(0.5+0.5*clamp(wind,0,5)/(1+clamp(wind,0,5)))*Math.pow(1.04,clamp(temperature,10,40)-25)*clamp(opening,0,100)/100;\n}\n", "src/lib/explorer/topics-data.json": "[\n  {\n    \"id\": \"simulations-ac-circuits\",\n    \"route\": \"/simulations/ac-circuits\",\n    \"subject\": \"Physics\",\n    \"title\": \"AC circuits\",\n    \"description\": \"Compare alternating voltage, current and the effects of resistance, inductance and capacitance.\",\n    \"principle\": \"V_rms = V_peak / √2 (sinusoidal voltage)\",\n    \"concept\": \"circuit\",\n    \"aliases\": [\n      \"ac circuits\",\n      \"ac circuits\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"speedMultiplier\",\n        \"label\": \"Animation speed\",\n        \"unit\": \"×\",\n        \"min\": 0.25,\n        \"max\": 3,\n        \"default\": 1\n      },\n      {\n        \"key\": \"vPeak\",\n        \"label\": \"Peak voltage\",\n        \"unit\": \"V\",\n        \"min\": 5,\n        \"max\": 50,\n        \"default\": 20\n      },\n      {\n        \"key\": \"frequency\",\n        \"label\": \"Frequency\",\n        \"unit\": \"Hz\",\n        \"min\": 0.5,\n        \"max\": 5,\n        \"default\": 2\n      },\n      {\n        \"key\": \"resistance\",\n        \"label\": \"Resistance\",\n        \"unit\": \"Ω\",\n        \"min\": 10,\n        \"max\": 500,\n        \"default\": 100\n      },\n      {\n        \"key\": \"inductance\",\n        \"label\": \"Inductance\",\n        \"unit\": \"H\",\n        \"min\": 0.1,\n        \"max\": 2,\n        \"default\": 0.5\n      },\n      {\n        \"key\": \"capacitance\",\n        \"label\": \"Capacitance\",\n        \"unit\": \"µF\",\n        \"min\": 1,\n        \"max\": 50,\n        \"default\": 10\n      },\n      {\n        \"key\": \"rlcFrequency\",\n        \"label\": \"Frequency\",\n        \"unit\": \"Hz\",\n        \"min\": 10,\n        \"max\": 200,\n        \"default\": 50\n      },\n      {\n        \"key\": \"parallelResistance\",\n        \"label\": \"Resistance\",\n        \"unit\": \"Ω\",\n        \"min\": 100,\n        \"max\": 3000,\n        \"default\": 1000\n      },\n      {\n        \"key\": \"resL\",\n        \"label\": \"Inductance\",\n        \"unit\": \"H\",\n        \"min\": 0.1,\n        \"max\": 2,\n        \"default\": 0.5\n      },\n      {\n        \"key\": \"resC\",\n        \"label\": \"Capacitance\",\n        \"unit\": \"µF\",\n        \"min\": 1,\n        \"max\": 50,\n        \"default\": 10\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"simulations-atomic-models\",\n    \"route\": \"/simulations/atomic-models\",\n    \"subject\": \"Physics\",\n    \"title\": \"Atomic models\",\n    \"description\": \"Compare models of atomic structure and the evidence behind them.\",\n    \"principle\": \"Atomic number Z = number of protons\",\n    \"concept\": \"atom\",\n    \"aliases\": [\n      \"atomic models\",\n      \"atomic models\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"speed\",\n        \"label\": \"Animation speed\",\n        \"unit\": \"×\",\n        \"min\": 0,\n        \"max\": 3,\n        \"default\": 1\n      },\n      {\n        \"key\": \"zoom\",\n        \"label\": \"Zoom\",\n        \"unit\": \"×\",\n        \"min\": 0.3,\n        \"max\": 3,\n        \"default\": 1\n      },\n      {\n        \"key\": \"protonCount\",\n        \"label\": \"Protons Z\",\n        \"unit\": \"\",\n        \"min\": 1,\n        \"max\": 92,\n        \"default\": 1,\n        \"integer\": true\n      },\n      {\n        \"key\": \"neutronCount\",\n        \"label\": \"Neutrons N\",\n        \"unit\": \"\",\n        \"min\": 0,\n        \"max\": 150,\n        \"default\": 0,\n        \"integer\": true\n      },\n      {\n        \"key\": \"alphaEnergy\",\n        \"label\": \"α-particle energy\",\n        \"unit\": \"MeV\",\n        \"min\": 1,\n        \"max\": 10,\n        \"default\": 5\n      },\n      {\n        \"key\": \"magneticField\",\n        \"label\": \"Magnetic field B\",\n        \"unit\": \"T\",\n        \"min\": 0,\n        \"max\": 5,\n        \"default\": 0\n      },\n      {\n        \"key\": \"nQuantum\",\n        \"label\": \"n\",\n        \"unit\": \"\",\n        \"min\": 1,\n        \"max\": 4,\n        \"default\": 1,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"simulations-band-theory\",\n    \"route\": \"/simulations/band-theory\",\n    \"subject\": \"Physics\",\n    \"title\": \"Band theory\",\n    \"description\": \"Explore how energy bands and carrier populations affect electrical conduction.\",\n    \"principle\": \"Band gap separates valence and conduction bands\",\n    \"concept\": \"band\",\n    \"aliases\": [\n      \"band theory\",\n      \"band theory\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"temperature\",\n        \"label\": \"Temperature\",\n        \"unit\": \"K\",\n        \"min\": 0,\n        \"max\": 1000,\n        \"default\": 300\n      },\n      {\n        \"key\": \"dopingConcentration\",\n        \"label\": \"Doping conc.\",\n        \"unit\": \"log₁₀(cm⁻³)\",\n        \"min\": 10,\n        \"max\": 20,\n        \"default\": 10\n      },\n      {\n        \"key\": \"speed\",\n        \"label\": \"Animation speed\",\n        \"unit\": \"×\",\n        \"min\": 0,\n        \"max\": 3,\n        \"default\": 1\n      },\n      {\n        \"key\": \"zoom\",\n        \"label\": \"Zoom\",\n        \"unit\": \"×\",\n        \"min\": 0.5,\n   