ult\": \"plant\",\n        \"options\": [\n          \"plant\",\n          \"animal\"\n        ]\n      },\n      {\n        \"key\": \"labels\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-mitosis\",\n    \"route\": \"/biology/mitosis\",\n    \"subject\": \"Biology\",\n    \"title\": \"Mitosis and the cell cycle\",\n    \"description\": \"Track one replication and one division, preserving chromosome set number.\",\n    \"principle\": \"Track one replication and one division, preserving chromosome set number.\",\n    \"concept\": \"bio-mitosis\",\n    \"aliases\": [\n      \"mitosis\",\n      \"cell cycle\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 5,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-meiosis\",\n    \"route\": \"/biology/meiosis\",\n    \"subject\": \"Biology\",\n    \"title\": \"Meiosis and genetic variation\",\n    \"description\": \"Track homologues then sister chromatids through two divisions and explore genetic variation.\",\n    \"principle\": \"Track homologues then sister chromatids through two divisions and explore genetic variation.\",\n    \"concept\": \"bio-meiosis\",\n    \"aliases\": [\n      \"meiosis\",\n      \"meiotic division\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 8,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [\n      {\n        \"key\": \"crossing\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      },\n      {\n        \"key\": \"orientation\",\n        \"default\": \"original\",\n        \"options\": [\n          \"original\",\n          \"alternate\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-transpiration\",\n    \"route\": \"/biology/transpiration\",\n    \"subject\": \"Biology\",\n    \"title\": \"Transpiration in plants\",\n    \"description\": \"Explore humidity, air movement, temperature and stomatal opening with an illustrative relative water-loss index.\",\n    \"principle\": \"Explore humidity, air movement, temperature and stomatal opening with an illustrative relative water-loss index.\",\n    \"concept\": \"bio-transpiration\",\n    \"aliases\": [\n      \"transpiration\",\n      \"plant water loss\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 3,\n        \"default\": 0,\n        \"integer\": true\n      },\n      {\n        \"key\": \"humidity\",\n        \"label\": \"Humidity\",\n        \"unit\": \"%\",\n        \"min\": 0,\n        \"max\": 100,\n        \"default\": 50\n      },\n      {\n        \"key\": \"wind\",\n        \"label\": \"Air movement\",\n        \"unit\": \"relative\",\n        \"min\": 0,\n        \"max\": 5,\n        \"default\": 1\n      },\n      {\n        \"key\": \"temperature\",\n        \"label\": \"Temperature\",\n        \"unit\": \"°C\",\n        \"min\": 10,\n        \"max\": 40,\n        \"default\": 25\n      },\n      {\n        \"key\": \"opening\",\n        \"label\": \"Stomatal opening\",\n        \"unit\": \"%\",\n        \"min\": 0,\n        \"max\": 100,\n        \"default\": 100\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-classification\",\n    \"route\": \"/biology/classification\",\n    \"subject\": \"Biology\",\n    \"title\": \"Classification and scientific names\",\n    \"description\": \"Search and compare 90 organisms across Domain and KPCOFGS, inspect source notes and practise scientific names.\",\n    \"principle\": \"Compare human and domestic cat ranks from Domain to Species and practise scientific names.\",\n    \"concept\": \"bio-classification\",\n    \"aliases\": [\n      \"classification\",\n      \"taxonomy\",\n      \"KPCOFGS\",\n      \"nomenclature\",\n      \"binomial naming\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 7,\n        \"default\": 0,\n        \"integer\": true\n      },\n      {\n        \"key\": \"organismIndex\",\n        \"label\": \"First organism\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 89,\n        \"default\": 0,\n        \"integer\": true\n      },\n      {\n        \"key\": \"comparisonIndex\",\n        \"label\": \"Comparison organism\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 89,\n        \"default\": 1,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [\n      {\n        \"key\": \"labels\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-life-processes\",\n    \"route\": \"/biology/life-processes\",\n    \"subject\": \"Biology\",\n    \"title\": \"Characteristics of living things\",\n    \"description\": \"Examine evidence for life, compare life processes and distinguish common misconceptions.\",\n    \"principle\": \"Examine evidence for life, compare life processes and distinguish common misconceptions.\",\n    \"concept\": \"bio-life-processes\",\n    \"aliases\": [\n      \"life processes\",\n      \"characteristics of living things\",\n      \"MRNIGERDCA\",\n      \"MRS GREN\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 9,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  }\n]\n", "src/components/biology/BiologyModel.tsx": "'use client';\nimport { Fragment } from 'react';\nimport { ClassificationModel } from './ClassificationModel';\nimport { lessons,type LessonId } from '@/lib/biology/lessons';\ntype Props={topic:LessonId;step:number;plant:boolean;crossing:boolean;orientation:boolean;index:number;phase:number;onSelect:(n:number)=>void;interactive:boolean;labels:boolean;primary?:number;comparison?:number};\nexport function BiologyModel({topic,step,plant,crossing,orientation,index,phase,onSelect,interactive,labels,primary,comparison}:Props){\n const lesson=lessons[topic];\n if(topic==='classification')return <ClassificationModel primary={primary} comparison={comparison} step={step} answers={labels}/>;\n if(topic==='life-processes')return <div className=\"bio-process-grid\">{lesson.steps.map((s,i)=><button key={s.name} className=\"bio-button\" aria-pressed={i===step} disabled={!interactive} onClick={()=>onSelect(i)}><span className=\"block text-xl\" aria-hidden=\"true\">{['↔','⚡','☀','◉','↗','↪','✧','⌛','⇄','🌿'][i]}</span>{s.name}</button>)}</div>;\n return <svg className=\"bio-model-svg\" viewBox=\"0 0 800 460\" role={topic==='cells'&&interactive?'group':'img'} aria-label={`${lesson.title}: ${lesson.steps[step].name}`}>\n <title>{`${lesson.title}: ${lesson.steps[step].name}`}</title><rect width=\"800\" height=\"460\" rx=\"20\" fill=\"#f0fdfa\"/>\n {topic==='cells'?<>\n {plant?<rect x=\"70\" y=\"35\" width=\"660\" height=\"385\" rx=\"45\" fill=\"#dcfce7\" stroke=\"#15803d\" strokeWidth=\"12\"/>:<ellipse cx=\"400\" cy=\"225\" rx=\"330\" ry=\"190\" fill=\"#fef3c7\" stroke=\"#0f766e\" strokeWidth=\"5\"/>}\n {plant&&<rect x=\"82\" y=\"47\" width=\"636\" height=\"361\" rx=\"37\" fill=\"none\" stroke=\"#0f766e\" strokeWidth=\"4\"/>}\n {lesson.steps.map((s,i)=>{if(!plant&&i>=5)return null;const [x,y]=[[115,220],[210,125],[300,250],[545,125],[560,340],[680,225],[600,235],[445,270]][i];return <g key={s.name} role={interactive?'button':undefined} tabIndex={interactive?0:undefined} aria-label={s.name} aria-pressed={i===step} onClick={()=>interactive&&onSelect(i)} onKeyDown={e=>{if(interactive&&(e.key==='Enter'||e.key===' ')){e.preventDefault();onSelect(i);}}} className=\"bio-hotspot\" style={{cursor:interactive?'pointer':undefined}}>\n <ellipse cx={x} cy={y} rx={i===2?63:i===7?70:38} ry={i===2?58:i===7?92:28} fill={['#99f6e4','#fde68a','#c4b5fd','#fdba74','#cbd5e1','#86efac','#4ade80','#bae6fd'][i]} stroke={i===step?'#b45309':'#334155'} strokeWidth={i===step?5:2}/>\n {i===3&&<path d={`M${x-22} ${y}q10 -20 20 0t20 0`} fill=\"none\" stroke=\"#9a3412\" strokeWidth=\"3\"/>}{i===4&&[0,1,2,3].map(n=><circle key={n} cx={x-18+n*12} cy={y} r=\"5\" fill=\"#475569\"/>)}\n {labels&&<text x={x} y={y+6} textAnchor=\"middle\" fontSize=\"16\" fill=\"#0f172a\" fontWeight=\"600\">{s.name}</text>}</g>;})}<text x=\"400\" y=\"445\" textAnchor=\"middle\" fontSize=\"17\">{plant?'Photosynthetic plant cell':'Typical animal cell'} · selected structures, not to scale</text>\n </>:topic==='transpiration'?<>\n <path d=\"M400 390V155M400 240L285 175M400 275L525 195\" stroke=\"#166534\" strokeWidth=\"20\" fill=\"none\"/>\n <ellipse cx=\"280\" cy=\"160\" rx=\"95\" ry=\"45\" transform=\"rotate(25 280 160)\" fill=\"#86efac\" stroke=\"#15803d\" strokeWidth=\"3\"/><ellipse cx=\"525\" cy=\"180\" rx=\"100\" ry=\"47\" transform=\"rotate(-25 525 180)\" fill=\"#86efac\" stroke=\"#15803d\" strokeWidth=\"3\"/>\n <path d=\"M400 390L325 435M400 390L460 435M400 400V445\" stroke=\"#92400e\" strokeWidth=\"7\"/><path d=\"M110 395H690\" stroke=\"#92400e\" strokeWidth=\"3\"/>\n {Array.from({length:12},(_,i)=>{const t=(i/12+phase*index/100)%1;return <circle key={i} cx={400} cy={385-t*205} r=\"5\" fill=\"#0284c7\" opacity={index>0?0.85:0}/>;})}\n {Array.from({length:6},(_,i)=><circle key={i} cx={560+((phase+i/6)%1)*90} cy={130-((phase+i/6)%1)*85} r=\"5\" fill=\"#0284c7\" opacity={index>0?Math.min(1,index/30):0}/>)}\n <text x=\"110\" y=\"370\" fontSize=\"20\">Roots → xylem → leaf → air</text><text x=\"470\" y=\"75\" fontSize=\"20\">Water vapour</text><text x=\"80\" y=\"40\" fontSize=\"20\">Relative index: {index.toFixed(1)}</text><text x=\"80\" y=\"450\" fontSize=\"16\">Blue dots illustrate flow; they are not counted water molecules.</text>\n </>:<Division topic={topic as 'mitosis'|'meiosis'} step={step} crossing={crossing} orientation={orientation}/>}\n </svg>;\n}\nfunction Division({topic,step,crossing,orientation}:{topic:'mitosis'|'meiosis';step:number;crossing:boolean;orientation:boolean}){\n const mei=topic==='meiosis',replicated=step>0,firstSplit=mei&&step>=5,finished=mei?step===8:step===5,anaphase=mei?(step===4||step===7):step===4;\n const cells=finished?(mei?4:2):firstSplit?2:1;\n const centres=cells===1?[[400,225]]:cells===2?[[215,225],[585,225]]:[[200,120],[600,120],[200,340],[600,340]];\n const colour=(h:number)=>h?'#c2410c':'#1d4ed8';\n function chromosome(x:number,y:number,pair:number,h:number,single:boolean,recombined:boolean,key:string){const length=pair===0?48:30;return <g key={key} data-chromosome data-chromatids={single?1:2} transform={`translate(${x} ${y})`} stroke={colour(h)} strokeWidth=\"7\" strokeLinecap=\"round\">\n {single?<path d={`M0 ${-length/2}V${length/2}`}/>:<><path d={`M-9 ${-length/2}L9 ${length/2}`}/><path d={`M9 ${-length/2}L-9 ${length/2}`}/></>}\n {recombined&&<path d={single?`M0 ${length/2-10}V${length/2}`:`M5 ${length/2-10}L9 ${length/2}`} stroke={colour(1-h)}/>}<circle r=\"3\" fill=\"#111827\" stroke=\"none\"/></g>;}\n return <>\n {centres.map(([cx,cy],cell)=>{const radius=cells===4?96:cells===2?155:185;const haploid=mei&&(firstSplit||finished);const members=haploid||(mei&&step===4)?2:4;\n return <Fragment key={cell}><ellipse cx={cx} cy={cy} rx={radius} ry={cells===4?90:radius} fill=\"#fff\" stroke=\"#0f766e\" strokeWidth=\"3\"/>\n {Array.from({length:members},(_,i)=>{const pair=haploid||(mei&&step===4)?i:Math.floor(i/2);let h=haploid?(cell%2):i%2;if(mei&&pair===1&&orientation)h=1-h;\n const align=mei?(step===3||step===6):step===3;\n const x=cx+(align?(haploid?0:(i%2?18:-18)):haploid?(i?30:-30):(i%2?45:-45));const y=cy+(pair?36:-36);\n const single=!replicated||finished;\n if(anaphase){return <Fragment key={i}>{[-1,1].map((pole,j)=>chromosome(cx+pole*radius*0.55+(!mei?(h?10:-10):0),y,pair,mei&&step===4?(pair===1&&orientation?1-j:j):h,mei&&step===4?false:true,mei&&crossing&&step>=2&&pair===0&&(j===1),`${i}-${j}`))}</Fragment>;}\n return chromosome(x,y,pair,h,single,mei&&crossing&&step>=2&&pair===0&&(finished?cell>=2:true),String(i));})}\n {labelsForCell(mei,step,cell,cx,cy,radius)}\n </Fragment>;})}\n <text x=\"400\" y=\"25\" textAnchor=\"middle\" fontSize=\"18\">Long + short chromosomes · blue/coral parental origins</text>\n </>;\n}\nfunction labelsForCell(mei:boolean,step:number,cell:number,x:number,y:number,r:number){const text=mei?(step===8?'n = 2 · 2 DNA molecules':step>=5?'n = 2 · 4 DNA molecules':step===0?'2n = 4 · 4 DNA molecules':step===4?'Each pole: n = 2, replicated':'2n = 4 · 8 DNA molecules'):(step===0||step===5?'2n = 4 · 4 DNA molecules':step===4?'Each pole: 4 chromosomes':'2n = 4 · 8 DNA molecules');return <text x={x} y={y+r-15} textAnchor=\"middle\" fontSize={r<100?13:16} fill=\"#0f172a\">{text}</text>;}\n", "src/components/biology/ClassificationModel.tsx": "'use client';\nimport { organisms, ranks, rankValue, type Organism } from '@/lib/biology/taxonomy';\nexport function ClassificationModel({primary=0,comparison=1,step=0,answers=true}:{primary?:number;comparison?:number;step?:number;answers?:boolean}){\n const left=organisms[primary]||organisms[0],right=organisms[comparison]||organisms[1];\n const shared=ranks.filter((_,i)=>{const a=rankValue(left,i),b=rankValue(right,i);return a&&b&&a===b;});\n return <div className=\"bio-classification\">\n <p className=\"mb-3 text-sm leading-6\"><strong>{organisms.length} organisms</strong> · GBIF Backbone reference snapshot · compare the same rank across two examples.</p>\n <div className=\"bio-taxonomy-scroll\" tabIndex={0} role=\"region\" aria-label=\"Organism rank comparison\"><table className=\"bio-taxonomy-table\"><caption className=\"sr-only\">Domain and KPCOFGS classification comparison</caption><thead><tr><th scope=\"col\">Rank</th><th scope=\"col\">{left.common}<br/><em>{left.name}</em></th><th scope=\"col\">{right.common}<br/><em>{right.name}</em></th></tr></thead><tbody>{ranks.map((rank,i)=>{const a=rankValue(left,i),b=rankValue(right,i),same=!!a&&a===b;return <tr key={rank} data-active={i===step} data-shared={same}><th scope=\"row\">{rank}{same&&<span className=\"block text-xs font-normal\">Shared</span>}{i===step&&<span className=\"block text-xs font-normal\">Selected rank</span>}</th>{[a,b].map((v,j)=><td key={j}>{!answers&&i===step?<span>Predict, then reveal</span>:v?<span className={i>=6?'italic':''}>{v}</span>:<span>Not assigned in this snapshot</span>}</td>)}</tr>;})}</tbody></table></div>\n <p className=\"my-3 text-sm leading-6\">{left.name===right.name?'You selected the same species twice. Choose a different example to compare.':`${shared.length} displayed ranks shared. Shared ranks describe this reference hierarchy, not a measurement of genetic similarity.`}</p>\n <div className=\"bio-organism-notes\">{[left,right].map((o,i)=><OrganismNotes key={i} organism={o}/>)}</div>\n <p className=\"my-3 text-xs leading-6\">Taxonomy data: GBIF Secretariat (2023), <a className=\"underline\" href=\"https://doi.org/10.15468/39omei\" target=\"_blank\" rel=\"noreferrer\">GBIF Backbone Taxonomy</a>, <a className=\"underline\" href=\"https://creativecommons.org/licenses/by/4.0/\" target=\"_blank\" rel=\"noreferrer\">CC BY 4.0</a>. Selected rank fields retrieved 3 November 2026; domain labels, common names and teaching notes added for this activity. This is the legacy Backbone reference, not a live Catalogue of Life lookup.</p>\n <details className=\"my-3 text-sm leading-6\"><summary className=\"cursor-pointer font-semibold\">School names and classification systems</summary><p className=\"mt-2\">KPCOFGS gives Kingdom, Phylum (often Division for plants), Class, Order, Family, Genus and Species; Domain is added above Kingdom. This table follows a saved GBIF Backbone hierarchy. Textbooks may use different ranks or names: compare the source and system before marking a different classification wrong.</p><p className=\"mt-2\">Traditional Monera combines bacteria and archaea; modern domain systems separate them. Protista is a historical teaching grouping, not one natural evolutionary branch. Traditional monocot/dicot and algal groupings may differ from this source’s ranked plant classification. A missing rank is left unassigned rather than invented. Viruses use a different ICTV hierarchy and are outside this organism table.</p><p className=\"mt-2\">Read-aloud and labels use scientific names as written. This collection supplies reference examples; it does not identify an unknown specimen.</p></details>\n </div>;\n}\nfunction OrganismNotes({organism:o}:{organism:Organism}){return <section><h3 className=\"font-semibold\">{o.common}</h3><p className=\"my-1 text-xs leading-6\">{o.note}</p><a className=\"text-xs underline\" href={o.source} target=\"_blank\" rel=\"noreferrer\">GBIF source · {o.name}</a><p className=\"text-xs text-gray-600\">Snapshot: {o.checked}</p></section>;}\n", "src/components/biology/BiologyLesson.tsx": "'use client';\nimport { useEffect,useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { ReadAloud } from '@/components/accessibility/ReadAloud';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\nimport { lessons,transpirationIndex,type LessonId } from '@/lib/biology/lessons';\nimport { BiologyModel } from './BiologyModel';\nimport { organisms, organismGroups, filterOrganisms } from '@/lib/biology/taxonomy';\nimport './biology.css';\nimport './biology-lessons.css';\nexport function BiologyLesson({topic,embed=false}:{topic:LessonId;embed?:boolean}){\n const lesson=lessons[topic];const [step,setStep]=useState(0),[running,setRunning]=useState(false),[speed,setSpeed]=useState(1),[plant,setPlant]=useState(true),[crossing,setCrossing]=useState(true),[orientation,setOrientation]=useState(false),[labels,setLabels]=useState(true),[controls,setControls]=useState(true);\n const [humidity,setHumidity]=useState(50),[wind,setWind]=useState(1),[temperature,setTemperature]=useState(25),[opening,setOpening]=useState(100),[phase,setPhase]=useState(0);\n const [tab,setTab]=useState<'student'|'teacher'>('student'),[question,setQuestion]=useState(0),[answers,setAnswers]=useState<Record<number,number>>({});\n const [primary,setPrimary]=useState(0),[comparison,setComparison]=useState(1),[search,setSearch]=useState(''),[group,setGroup]=useState('All');\n const organismChoices=filterOrganisms(search,group);\n const division=topic==='mitosis'||topic==='meiosis',current=lesson.steps[step],quiz=lesson.questions[question],answered=answers[question]!==undefined;\n const index=transpirationIndex(humidity,wind,temperature,opening);\n function chooseStep(n:number){setStep(Math.max(0,Math.min(lesson.steps.length-1,Math.trunc(n))));setRunning(false);}\n useTopicPreset('biology-'+topic,{step:chooseStep,humidity:setHumidity,wind:setWind,temperature:setTemperature,opening:setOpening,organismIndex:setPrimary,comparisonIndex:setComparison},{cell:v=>{setPlant(v==='plant');if(v==='animal')setStep(n=>Math.min(n,4));},crossing:v=>setCrossing(v==='on'),orientation:v=>setOrientation(v==='alternate'),labels:v=>setLabels(v==='on')});\n useEffect(()=>{const q=new URLSearchParams(window.location.search);for(const [key,lo,hi,set]of [['step',0,lesson.steps.length-1,setStep],['humidity',0,100,setHumidity],['wind',0,5,setWind],['temperature',10,40,setTemperature],['opening',0,100,setOpening]] as const){const v=Number(q.get(key));if(q.has(key)&&Number.isFinite(v))set(key==='step'?Math.trunc(Math.max(lo,Math.min(hi,v))):Math.max(lo,Math.min(hi,v)));}for(const [key,set] of [['organism',setPrimary],['compare',setComparison]] as const){const n=Number(q.get(key));if(q.has(key)&&Number.isInteger(n)&&n>=0&&n<organisms.length)set(n);}if(q.get('cell')==='animal'){setPlant(false);setStep(n=>Math.min(n,4));}if(q.get('crossing')==='off')setCrossing(false);if(q.get('orientation')==='alternate')setOrientation(true);if(q.get('labels')==='off')setLabels(false);if(embed&&q.get('controls')==='0')setControls(false);},[embed,lesson.steps.length]);\n useEffect(()=>{if(!running||!division)return;const timer=setInterval(()=>setStep(n=>{if(n>=lesson.steps.length-1)return n;return n+1;}),1800/speed);return()=>clearInterval(timer);},[running,speed,division,lesson.steps.length]);\n useEffect(()=>{if(division&&step===lesson.steps.length-1)setRunning(false);},[step,division,lesson.steps.length]);\n useEffect(()=>{if(!running||topic!=='transpiration')return;const timer=setInterval(()=>setPhase(p=>(p+0.025*speed)%1),50);return()=>clearInterval(timer);},[running,topic,speed]);\n function reset(){setPrimary(0);setComparison(1);setSearch('');setGroup('All');setStep(0);setRunning(false);setSpeed(1);setPlant(true);setCrossing(true);setOrientation(false);setLabels(true);setHumidity(50);setWind(1);setTemperature(25);setOpening(100);setPhase(0);setQuestion(0);setAnswers({});}\n const steps=topic==='cells'&&!plant?lesson.steps.slice(0,5):lesson.steps;\n return <div className=\"bio-page\">{!embed&&<AppHeader/>}<main className={embed?'bio-embed':'mx-auto max-w-7xl px-3 py-6 sm:px-6'}>\n {!embed&&<><Link href=\"/biology\" className=\"text-sm text-teal-800 underline\">← Biology</Link><h1 className=\"my-3 text-2xl font-semibold\">{lesson.title}</h1><p className=\"mb-4 max-w-3xl text-sm leading-7\">{lesson.intro}</p></>}\n <SimulationStage className={`af-biology-lesson-stage ${embed?'af-embed-stage':''}`}>\n <div data-stage-role=\"canvas\" className=\"bio-lesson-scene\"><div className=\"bio-model\"><BiologyModel topic={topic} step={step} plant={plant} crossing={crossing} orientation={orientation} index={index} phase={phase} onSelect={chooseStep} interactive={controls} labels={labels} primary={primary} comparison={comparison}/></div><aside className=\"bio-lesson-note\"><p className=\"text-xs font-semibold uppercase text-teal-800\">{lesson.title}</p><h2 className=\"my-2 text-lg font-semibold\">{current.name}</h2><p className=\"text-sm leading-7\">{current.detail}</p><ReadAloud text={`${current.name}. ${current.detail}`} language=\"en\"/>{topic==='transpiration'&&<p className=\"my-3 text-sm\"><strong>Relative index: {index.toFixed(1)}</strong><br/>Illustrative units · not mL/hour</p>}<p className=\"mt-4 text-xs leading-6 text-gray-600\">{lesson.limit}</p></aside></div>\n {controls&&<div data-stage-role=\"parameters\" className=\"bio-controls\">\n <label>{division?'Stage':'Explore'}<select value={step} onChange={e=>chooseStep(+e.target.value)}>{steps.map((s,i)=><option key={s.name} value={i}>{s.name}</option>)}</select></label>\n {topic==='classification'&&<>\n <label>Search common / scientific name<input type=\"search\" value={search} placeholder=\"e.g. maize, frog, Rhizopus\" onChange={e=>setSearch(e.target.value)}/></label>\n <label>Organism group<select value={group} onChange={e=>setGroup(e.target.value)}>{['All',...organismGroups].map(g=><option key={g}>{g}</option>)}</select></label>\n {([['First organism',primary,setPrimary],['Compare with',comparison,setComparison]] as const).map(([label,selected,set])=><label key={label}>{label}<select value={selected} onChange={e=>set(+e.target.value)}>{organisms.map((o,i)=>({o,i})).filter(({o,i})=>i===selected||organismChoices.includes(o)).map(({o,i})=><option key={o.id} value={i}>{o.common} · {o.name}</option>)}</select></label>)}\n <span className=\"bio-organism-count\" role=\"status\">{organismChoices.length} matching / {organisms.length} total · current choices remain available</span>\n <label>Reveal selected rank<input type=\"checkbox\" checked={labels} onChange={e=>setLabels(e.target.checked)}/></label>\n </>}\n {topic==='cells'&&<><label>Cell type<select value={plant?'plant':'animal'} onChange={e=>{setPlant(e.target.value==='plant');setStep(0);}}><option value=\"plant\">Plant</option><option value=\"animal\">Animal</option></select></label><label>Labels<input type=\"checkbox\" checked={labels} onChange={e=>setLabels(e.target.checked)}/></label></>}\n {topic==='meiosis'&&<><label>Crossing over<input type=\"checkbox\" checked={crossing} onChange={e=>setCrossing(e.target.checked)}/></label><label>Pair orientation<select value={orientation?'alternate':'original'} onChange={e=>setOrientation(e.target.value==='alternate')}><option value=\"original\">Original</option><option value=\"alternate\">Flip short pair</option></select></label></>}\n {topic==='transpiration'&&<>{([['Humidity (%)',humidity,0,100,1,setHumidity],['Air movement (relative)',wind,0,5,0.1,setWind],['Temperature (°C)',temperature,10,40,1,setTemperature],['Stomatal opening (%)',opening,0,100,1,setOpening]] as const).map(([label,value,min,max,increment,set])=><label key={label}>{label}: {value}<input type=\"range\" value={value} min={min} max={max} step={increment} onChange={e=>set(+e.target.value)}/></label>)}</>}\n {(division||topic==='transpiration')&&<label>Playback speed<select value={speed} onChange={e=>setSpeed(+e.target.value)}>{[0.5,1,2].map(n=><option value={n} key={n}>{n}×</option>)}</select></label>}\n </div>}\n {controls&&<div data-stage-role=\"playback\" className=\"flex flex-wrap gap-2 p-2\">{(division||topic==='transpiration')&&<button className=\"bio-button\" onClick={()=>{if(division&&step===lesson.steps.length-1)setStep(0);setRunning(v=>!v);}}>{running?'Pause':'Run'}</button>}<button className=\"bio-button\" disabled={step===0} onClick={()=>chooseStep(step-1)}>Previous</button><button className=\"bio-button\" disabled={step>=steps.length-1} onClick={()=>chooseStep(step+1)}>Next</button><button className=\"bio-button\" onClick={reset}>Reset lesson</button>{!embed&&<EmbedButton path={'/embed/'+topic} title={lesson.title} width={1000} height={700} params={{step,...(topic==='classification'?{organism:primary,compare:comparison}:{}),cell:plant?'plant':'animal',crossing:crossing?'on':'off',orientation:orientation?'alternate':'original',labels:labels?'on':'off',humidity,wind,temperature,opening}}/>}</div>}\n </SimulationStage>\n {!embed&&<section className=\"mt-5\"><div className=\"my-3 flex gap-2\" role=\"group\" aria-label=\"Learning sections\">{(['student','teacher'] as const).map(t=><button key={t} className=\"bio-button\" aria-pressed={tab===t} onClick={()=>setTab(t)}>{t==='student'?'Student activities':'Teacher guide'}</button>)}</div>\n {tab==='teacher'?<div className=\"bio-card\"><h2 className=\"text-lg font-semibold\">Teacher guide · 35-minute lesson</h2><p className=\"my-3 text-sm leading-7\"><strong>Learning objective:</strong> {lesson.principle}</p><ol className=\"list-decimal space-y-2 pl-5 text-sm leading-7\"><li>0–5 min: elicit an explanation and record predictions.</li><li>5–15 min: expand classroom view, then model one change or stage at a time.</li><li>15–25 min: {lesson.teacher}</li><li>25–30 min: pairs complete the student investigations and explain their evidence.</li><li>30–35 min: use a practice question as an exit ticket; ask for a reason as well as an answer.</li></ol>{topic==='classification'&&<p className=\"my-3 text-sm leading-7\">Pair activities: compare maize with rice, cat with lion, yeast with bread mould, and Amoeba with a bacterium. Ask learners to name the narrowest displayed shared rank, explain missing ranks, and locate a source before challenging an unfamiliar name. Hide the selected rank, take predictions, then reveal it.</p>}<h3 className=\"mt-4 font-semibold\">Misconception check</h3><p className=\"my-2 text-sm leading-7\">{lesson.misconception}</p><h3 className=\"mt-4 font-semibold\">Access and extension</h3><p className=\"my-2 text-sm leading-7\">Use step controls instead of timed playback, keyboard controls and read-aloud. Let one learner operate while a partner explains; swap roles. Extend the task by identifying one limitation of the model.</p><button className=\"bio-button\" onClick={()=>{setTab('student');setRunning(false);}}>Open student practice</button></div>:<div className=\"bio-card\"><h2 className=\"text-lg font-semibold\">Investigate and explain</h2><ol className=\"my-3 list-decimal space-y-2 pl-5 text-sm leading-7\">{lesson.investigation.map(t=><li key={t}>{t}</li>)}</ol><h3 className=\"mt-5 font-semibold\">Practice · question {question+1}/{lesson.questions.length}</h3><p className=\"my-3 text-sm leading-7\">{quiz.prompt}</p><div className=\"flex flex-wrap gap-2\">{quiz.choices.map((c,i)=><button key={c} className=\"bio-button\" disabled={answered} aria-pressed={answered&&answers[question]===i} onClick={()=>setAnswers(a=>question in a?a:{...a,[question]:i})}>{c}</button>)}</div><p role=\"status\" className=\"my-3 text-sm leading-7\">{answered?`${answers[question]===quiz.answer?'Correct.':'Review this answer.'} ${quiz.why}`:'Choose once, then discuss your reasoning.'}</p><p className=\"my-3 text-sm\">First attempts: {Object.entries(answers).filter(([n,a])=>a===lesson.questions[+n].answer).length}/{Object.keys(answers).length}</p><button className=\"bio-button\" onClick={()=>setQuestion(n=>(n+1)%lesson.questions.length)}>Next question</button><details className=\"my-4\"><summary className=\"cursor-pointer font-semibold\">Assignment and explanation guide</summary><p className=\"my-3 text-sm leading-7\">Write a claim, support it with two observations from this activity, and explain one model limitation. Compare with a partner. A strong answer names the structures or processes, controls relevant variables and distinguishes the illustration from biological evidence.</p></details></div>}</section>}\n <footer className=\"my-5 text-xs leading-6 text-gray-600\"><p>{lesson.limit} Activities and practice remain on this device; they do not create a shared live classroom or store student records.</p><a className=\"underline\" href={'https://openstax.org/books/biology-2e/pages/'+lesson.source} target=\"_blank\" rel=\"noreferrer\">Reference reading · OpenStax Biology 2e</a>{embed&&<Link className=\"ml-4 underline\" href={'/biology/'+topic} target=\"_blank\">Open full lesson</Link>}</footer>\n </main></div>;\n}\n", "src/components/biology/biology-lessons.css": ".bio-lesson-scene{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:1rem;background:white;border:1px solid #cbd5e1;border-radius:1rem;padding:.75rem}\n.bio-model{min-width:0;display:flex;align-items:center;justify-content:center;background:#f0fdfa;border-radius:.75rem;overflow:auto;min-height:280px}\n.bio-model-svg{width:100%;height:auto;max-height:70vh;display:block}.bio-lesson-note{padding:.75rem;overflow:auto;min-height:0}\n.bio-taxonomy{width:100%;padding:1rem;min-width:280px}.bio-rank{display:grid;grid-template-columns:1fr 1fr 1fr;gap:.5rem;border:1px solid #5eead4;background:white;border-radius:.5rem;padding:.6rem;margin-bottom:.4rem;font-size:.9rem}.bio-taxonomy p{font-size:.8rem;margin-top:1rem}.bio-process-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem;padding:1rem;width:100%}.bio-hotspot:focus-visible{outline:4px solid #b45309}\n.af-biology-lesson-stage[data-expanded=\"true\"] .bio-lesson-scene{height:var(--af-stage-canvas-height);min-height:0;overflow:hidden;grid-template-columns:minmax(0,1fr) clamp(200px,28vw,320px)}\n.af-biology-lesson-stage[data-expanded=\"true\"] .bio-model{min-height:0;height:100%}.af-biology-lesson-stage[data-expanded=\"